import ast,sys
src=open('/app/submission/main.py').read()
tree=ast.parse(src)
mods=set()
for n in ast.walk(tree):
    if isinstance(n, ast.Import):
        for a in n.names: mods.add(a.name)
    elif isinstance(n, ast.ImportFrom): mods.add(n.module)
print('imports:', sorted(mods))
